            m0 := or(m0, shl(24, and(shr(24, x), 0xff)))
            m0 := or(m0, shl(32, and(shr(32, x), 0xff)))
            m0 := or(m0, shl(40, and(shr(40, x), 0xff)))
            m0 := or(m0, shl(48, and(shr(48, x), 0xff)))
            m0 := or(m0, shl(56, and(shr(56, x), 0xff)))
            m0 := or(m0, shl(64, and(shr(64, x), 0xff)))
            m0 := or(m0, shl(72, and(shr(72, x), 0xff)))
            m0 := or(m0, shl(80, and(shr(80, x), 0xff)))
            m0 := or(m0, shl(88, and(shr(88, x), 0xff)))
            m0 := or(m0, shl(96, and(shr(96, x), 0xff)))
            m0 := or(m0, shl(104, and(shr(104, x), 0xff)))
            m0 := or(m0, shl(112, and(shr(112, x), 0xff)))
            m0 := or(m0, shl(120, and(shr(120, x), 0xff)))
            let m1 := or(and(m0, 0x0000000000000000ffffffffffffffff), shr(64, and(m0, 0xffffffffffffffff0000000000000000)))
            m0 := or(and(m1, 0x0000ffffffffffffffff0000ffffffffffffffff), shr(32, and(m1, 0xffffffff0000ffffffffffffffff0000ffffffff)))
            r := or(and(m0, 0x00000000ffffffff00000000ffffffff00000000ffffffff00000000ffffffff), shr(16, and(m0, 0xffff0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff0000ffff)))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   BOOLEAN OPERATIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Performs a bitwise AND operation on two boolean values using inline assembly.
    ///
    /// @param x The first boolean value.
    /// @param y The second boolean value.
    /// @return z The result of the bitwise AND operation between `x` and `y`.
    function rawAnd(bool x, bool y) internal pure returns (bool z) {
        /// @solidity memory-safe-assembly
        assembly {
            z := and(x, y)
        }
    }

